let issues = [];

for (const item of $input.all()) {

  const row = item.json;

  if (!row.Customer_Name || row.Customer_Name === "N/A") {
    issues.push({
      Order_ID: row.Order_ID,
      Issue: "Missing Customer Name"
    });
  }

  if (!row.Quantity || isNaN(Number(row.Quantity))) {
    issues.push({
      Order_ID: row.Order_ID,
      Issue: "Invalid Quantity"
    });
  }

  if (!row.Unit_Price) {
    issues.push({
      Order_ID: row.Order_ID,
      Issue: "Missing Unit Price"
    });
  }

  if (Number(row.Quantity) < 0) {
    issues.push({
      Order_ID: row.Order_ID,
      Issue: "Negative Quantity"
    });
  }
}

return issues.map(i => ({ json: i }));

const cleaned = [];

function cleanDate(value) {
  if (!value) return "Unknown Date";

  let dateText = value.toString().trim();

  // If Excel gives a serial number date
  if (!isNaN(dateText) && dateText !== "") {
    const excelEpoch = new Date(1899, 11, 30);
    excelEpoch.setDate(excelEpoch.getDate() + Number(dateText));
    return excelEpoch.toISOString().split("T")[0];
  }

  // Handles dates like 3-Jan-25, 19-Jan-25
  let parsedDate = new Date(dateText);

  if (!isNaN(parsedDate)) {
    return parsedDate.toISOString().split("T")[0];
  }

  // Handles dates like 13-01-2025 or 16/01/2025
  const parts = dateText.split(/[-\/]/);

  if (parts.length === 3) {
    let day = parts[0].padStart(2, "0");
    let month = parts[1].padStart(2, "0");
    let year = parts[2];

    if (year.length === 2) {
      year = "20" + year;
    }

    return `${year}-${month}-${day}`;
  }

  return "Invalid Date";
}

for (const item of $input.all()) {
  let row = item.json;

  // Clean Order Date
  row.Order_Date = cleanDate(row.Order_Date);

  // Clean Customer Name
  if (
    !row.Customer_Name ||
    row.Customer_Name.toString().trim() === "" ||
    row.Customer_Name.toString().trim().toUpperCase() === "N/A"
  ) {
    row.Customer_Name = "Unknown Customer";
  } else {
    row.Customer_Name = row.Customer_Name.toString().trim();
  }

  // Clean Product
  if (row.Product) {
    row.Product = row.Product.toString().trim();
    row.Product =
      row.Product.charAt(0).toUpperCase() +
      row.Product.slice(1).toLowerCase();
  } else {
    row.Product = "Unknown Product";
  }

  // Clean Category
  if (
    !row.Category ||
    row.Category.toString().trim() === "" ||
    row.Category.toString().trim().toLowerCase() === "ta"
  ) {
    row.Category = "Unknown Category";
  } else {
    row.Category = row.Category.toString().trim();
  }

  // Clean Quantity
  let quantity = Number(row.Quantity);

  if (isNaN(quantity) || quantity <= 0) {
    row.Quantity = 0;
  } else {
    row.Quantity = quantity;
  }

  // Clean Unit Price
  let unitPrice = Number(row.Unit_Price);

  if (isNaN(unitPrice) || unitPrice <= 0) {
    row.Unit_Price = 0;
  } else {
    row.Unit_Price = unitPrice;
  }

  // Clean State
  if (!row.State || row.State.toString().trim() === "") {
    row.State = "Unknown State";
  } else {
    const state = row.State.toString().toLowerCase().trim();

    if (
      state === "wb" ||
      state === "west bengal" ||
      state === "kolkata"
    ) {
      row.State = "West Bengal";
    } else {
      row.State = row.State.toString().trim();
    }
  }

  // Clean Salesperson
  if (!row.Salesperson || row.Salesperson.toString().trim() === "") {
    row.Salesperson = "Unknown Salesperson";
  } else {
    row.Salesperson = row.Salesperson.toString().trim();
  }

  cleaned.push({
    json: row
  });
}

return cleaned;

const rows = $input.all();

let totalRevenue = 0;
let totalOrders = 0;

const productSales = {};
const salespersonSales = {};

for (const item of rows) {

  const row = item.json;

  const quantity = Number(row.Quantity);
  const price = Number(row.Unit_Price);

  if (
    !isNaN(quantity) &&
    !isNaN(price) &&
    quantity > 0
  ) {

    const revenue = quantity * price;

    totalRevenue += revenue;
    totalOrders++;

    // Product totals
    if (!productSales[row.Product]) {
      productSales[row.Product] = 0;
    }

    productSales[row.Product] += revenue;

    // Salesperson totals
    if (!salespersonSales[row.Salesperson]) {
      salespersonSales[row.Salesperson] = 0;
    }

    salespersonSales[row.Salesperson] += revenue;
  }
}

const topProduct =
  Object.entries(productSales)
    .sort((a, b) => b[1] - a[1])[0];

const topSalesperson =
  Object.entries(salespersonSales)
    .sort((a, b) => b[1] - a[1])[0];

return [
  {
    json: {
      Total_Orders: totalOrders,
      Total_Revenue: totalRevenue,
      Top_Product: topProduct?.[0],
      Top_Product_Revenue: topProduct?.[1],
      Top_Salesperson: topSalesperson?.[0],
      Top_Salesperson_Revenue: topSalesperson?.[1]
    }
  }
];
